/* Offline presentation model. It never reads or changes device networking. */
(() => {
 'use strict';
 const platform=document.documentElement.dataset.platform;
 const mobile=platform==='android';
 const root=document.getElementById('app');
 const dialog=document.getElementById('dialog');
 const screens=window.LERNET_SCREENS;
 let mode='vpn',screen='vpn',state='ready',scopeOwner='device',selectedNode=null,zoom=1,dirty=false,revision=16,opener=null;
 const paths={
  home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',
  folder:'M3 7h7l2-3h7a2 2 0 012 2v12a2 2 0 01-2 2H5a2 2 0 01-2-2V7z',
  route:'M12 3v6M5 15v6M19 15v6M5 15V9h14v6M9 3h6M2 21h6M16 21h6',
  shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zM8 12l3 3 5-6',
  activity:'M3 12h4l3-8 4 16 3-8h4',
  globe:'M21 12a9 9 0 11-18 0 9 9 0 0118 0zM3 12h18M12 3c-5 5-5 13 0 18M12 3c5 5 5 13 0 18',
  settings:'M12 8a4 4 0 100 8 4 4 0 000-8zM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3z',
  arrows:'M8 20V4M4 8l4-4 4 4M16 4v16M12 16l4 4 4-4',
  swap:'M20 8a8 8 0 00-14-2L3 9M3 4v5h5M4 16a8 8 0 0014 2l3-3M21 20v-5h-5',
  more:'M12 5h.01M12 12h.01M12 19h.01',
  plus:'M12 5v14M5 12h14',check:'M5 12l4 4L19 6',close:'M6 6l12 12M18 6L6 18',
  chevron:'M9 5l7 7-7 7',arrow:'M4 12h16M15 7l5 5-5 5',back:'M20 12H4M9 7l-5 5 5 5',
  power:'M12 3v9M6 5a9 9 0 1012 0',filter:'M3 4h18l-7 8v7l-4 2v-9L3 4z',
  moon:'M20 15A9 9 0 119 3a7 7 0 0011 12z',clock:'M21 12a9 9 0 11-18 0 9 9 0 0118 0zM12 7v5l3 2',
  alert:'M12 3L2 21h20L12 3zM12 9v5M12 17h.01',info:'M21 12a9 9 0 11-18 0 9 9 0 0118 0zM12 11v6M12 7h.01',
  download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',
  laptop:'M5 3h14v13H5zM2 20h20l-3-4H5l-3 4z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
  search:'M17 17l4 4M19 10a9 9 0 11-18 0 9 9 0 0118 0z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7zM15 12a3 3 0 11-6 0 3 3 0 016 0z',
  portal:'M8 3c-7 0-7 18 0 18M16 3c7 0 7 18 0 18M5 12h14M14 7l5 5-5 5',
  lock:'M5 10h14v11H5zM8 10V7a4 4 0 118 0v3',edit:'M4 16L16 4l4 4L8 20H4v-4zM13 7l4 4',
  file:'M5 3h9l5 5v13H5zM14 3v5h5M8 13h8M8 17h6',copy:'M9 8h11v13H9zM15 8V3H4v13h5',
  wifi:'M2 8a16 16 0 0120 0M5 12a11 11 0 0114 0M8 16a6 6 0 018 0M12 20h.01',
  bolt:'M13 2L4 14h7l-1 8 10-12h-7l0-8',server:'M3 3h18v7H3zM3 14h18v7H3zM6 7h.01M6 18h.01',
  menu:'M3 6h18M3 12h18M3 18h18',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
  expand:'M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6',pause:'M8 4v16M16 4v16',play:'M7 3l14 9-14 9V3'
 };
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
 const url=(id,s)=>{const q=new URLSearchParams();if(s)q.set('state',s);if(mode==='vpn'&&['schema','routes-list','rule','application-picker','target-picker','folder-policy','lifecycle','exit-detail','redirect','test-route'].includes(id)){q.set('mode','vpn');q.set('owner','folder');}return '#'+id+(q.size?'?'+q:'');};
 const link=(id,label,kind='',ico='')=>`<a class="btn ${kind}" href="${url(id)}">${ico?icon(ico):''}${label}</a>`;
 const btn=(label,action,kind='',ico='')=>`<button type="button" class="btn ${kind}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
 const ib=(name,action,label)=>`<button type="button" class="icon-btn" data-action="${action}" aria-label="${label}" title="${label}">${icon(name)}</button>`;
 const chip=(label,tone='',ico='')=>`<span class="chip ${tone}">${ico?icon(ico):''}${label}</span>`;
 const notice=(title,body,tone='',ico='info')=>`<div class="notice ${tone}">${icon(ico)}<div><strong>${title}</strong>${body?`<p>${body}</p>`:''}</div></div>`;
 const panel=(title,body,action='')=>`<section class="panel"><div class="panel-header"><h2>${title}</h2>${action}</div>${body}</section>`;
 const field=(id,label,value='',help='',type='text')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}">${help?`<small>${help}</small>`:''}</div>`;
 const select=(id,label,items,help='')=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${items.map(v=>`<option>${v}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;
 const toggle=(id,title,help='',on=true)=>`<label class="switch-row" for="${id}"><span><strong>${title}</strong>${help?`<p>${help}</p>`:''}</span><input class="switch" type="checkbox" id="${id}" ${on?'checked':''}></label>`;
 const kv=(items)=>`<dl class="kv">${items.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
 const appIcon=(name='folder',text='')=>`<span class="app-icon ${name}">${text||icon(name)}</span>`;
 const row=(title,body,ico='info',action='',tone='')=>`<div class="row">${appIcon(ico)}<div class="grow"><div class="row-title ${tone}">${title}</div><p>${body}</p></div>${action}</div>`;
 const help=(title,body)=>`<div class="help-box"><strong>${title}</strong><p>${body}</p></div>`;
 const actions=(items)=>`<div class="form-actions">${items}</div>`;
 const stateLabel={ready:'Работает',off:'Выключено',blocked:'Нет рабочего выхода',waking:'Подключаем выход',failover:'Переключаем профиль',loading:'Получаем данные',error:'Нужна проверка',permission:'Нужно разрешение'};
 const stateNotice=()=>({
  permission:notice('Нужно разрешение',mobile?'Android ещё не разрешил LerNET обрабатывать трафик. Схему можно редактировать до включения.':'Нет прав администратора. Обычный прокси доступен; Expert mode требует разрешения на TUN.','warning','shield'),
  stale:notice('Снимок устарел','Это сохранённые данные на 11:38. Они не подтверждают текущее состояние сети. Обновите снимок.','warning','clock'),
  partial:notice('Часть данных недоступна',mobile?'Android не раскрывает владельца чужого VPN и системные фильтры. Эти поля помечены недоступными.':'Системный журнал блокировок недоступен. Из списка фильтров нельзя сделать вывод, какой из них остановил соединение.','warning'),
  incompatible:notice('Ветка другой платформы сохранена',mobile?'Условие по Windows-процессу не выполняется на Android. Можно добавить отдельную ветку Android.':'Условие по пакету Android не выполняется на Windows. Можно добавить отдельную ветку Windows.','warning'),
  blocked:notice('Защищённая ветка остановлена','В папке «Германия» нет доступного профиля. Telegram не выходит напрямую. Остальные ветки продолжают работать.','error','lock'),
  waking:notice('Первый запрос пробуждает выход','Ожидают 2 соединения Telegram. До готовности выхода прямой доступ для этой ветки запрещён.','', 'clock'),
  failover:notice('Меняем выход только для этой ветки','Германия-1 не отвечает через туннель. Проверяем Германия-2. Общий TUN продолжает работать.','warning','swap'),
  error:notice('Изменение не применено','Работает предыдущая схема №16. Черновик сохранён. Откройте причину и повторите попытку.','error','alert')
 }[state]||'');
 function parse(){const [id,q]=location.hash.slice(1).split('?');screen=screens.some(x=>x.id===id)?id:'vpn';const params=new URLSearchParams(q||'');state=params.get('state')||'ready';scopeOwner=params.get('owner')||'device';if(!LERNET_STATES.some(x=>x.id===state))state='ready';const group=screens.find(x=>x.id===screen).group;if(group==='Эксперт')mode=params.get('mode')==='vpn'?'vpn':'expert';if(group==='VPN'||group==='Начало')mode='vpn';}
 function nav(items){return items.map(([id,name,ico])=>`<a class="nav-link ${screen===id?'active':''}" href="${url(id)}" ${screen===id?'aria-current="page"':''}>${icon(ico)}${name}</a>`).join('');}
 function render(){
  parse();document.body.dataset.screen=screen;document.body.dataset.state=state;const definition=screens.find(x=>x.id===screen);
  const menu=mode==='expert'?[['expert','Обзор','home'],['schema','Схема','route'],['traffic','Трафик','activity'],['exits','Выходы','server'],['events','События','clock']]:[['vpn','Подключение','power'],['profiles','Профили','folder'],['schema','Маршруты','route'],['traffic','Диагностика','activity']];
  const bottom=mode==='expert'?[['expert','Обзор','home'],['schema','Схема','route'],['traffic','Трафик','activity'],['exits','Выходы','server']]:[['vpn','VPN','power'],['profiles','Профили','folder'],['schema','Маршруты','route'],['traffic','Диагностика','activity']];
  const headingActions=pageActions();
  document.body.classList.toggle('is-schema',screen==='schema');root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/lernet-icon.png" alt=""><div><div class="brand-name">LerNET</div><small>для Windows</small></div></div><nav aria-label="Основная навигация">${nav(menu)}</nav><div class="nav-spacer"></div><nav>${nav([['network','Сеть устройства','globe'],['settings','Настройки','settings']])}</nav><div class="sidebar-foot">LerNET v1.1.0<br>Данные остаются на устройстве</div></aside><div class="workspace"><div class="statusbar"><span>12:41</span><span>Wi-Fi · 84%</span></div><header class="mobile-header"><div class="brand"><img src="assets/lernet-icon.png" alt=""><span class="brand-name">LerNET</span></div><div class="inline">${ib('menu','navigation','Все разделы')}${ib('settings','settings','Настройки')}</div></header><header class="topbar"><nav class="mode-tabs" aria-label="Режим управления"><a href="#vpn" class="${mode==='vpn'?'active':''}" ${mode==='vpn'?'aria-current="true"':''}>${icon('power')}VPN</a><a href="#expert" class="${mode==='expert'?'active':''}" ${mode==='expert'?'aria-current="true"':''}>${icon('route')}Эксперт</a></nav><div class="top-status"><span class="status-dot ${state==='off'?'gray':['blocked','failover','error'].includes(state)?'yellow':''}"></span>${mode==='expert'?'Общий TUN':'Подключение'} · ${stateLabel[state]||'Работает'}${ib('settings','settings','Настройки')}</div></header><main class="page ${screen==='schema'?'schema-page':''}" id="main"><div class="page-head"><div><div class="eyebrow">${mode==='expert'?'Управление сетью':'LerNET'} / ${definition.group}</div><h1 tabindex="-1" id="page-title">${definition.title}</h1><p>${pageSubtitle()}</p></div>${headingActions?`<div class="head-actions">${headingActions}</div>`:''}</div>${stateNotice()}${state==='loading'&&!['update-progress'].includes(screen)?loading():state==='empty'&&!['schema','routes-list','expert'].includes(screen)?empty():renderPage()}<div class="bottom-spacer"></div></main></div></div><nav class="bottom-nav" aria-label="Основная навигация">${bottom.map(([id,name,ico])=>`<a href="#${id}" class="${screen===id?'active':''}" ${screen===id?'aria-current="page"':''}>${icon(ico)}${name}</a>`).join('')}</nav>`;
  if(screen==='schema')installGraph();document.querySelectorAll('.scope-select').forEach(el=>el.selectedIndex=scopeOwner==='folder'?1:scopeOwner==='profile'?2:0);
 }
 function pageSubtitle(){const map={vpn:'Подключение без лишних настроек.',profiles:'Папки объединяют профили и помогают пережить отказ сервера.',expert:'Один TUN. Свои правила для каждой части сети.',schema:'Черновик можно менять, пока работает сохранённая схема.',traffic:'Кто соединяется, куда идёт и какое правило сработало.',network:`${mobile?'Android 15':'Windows 11'} · снимок 12:41 · ${mobile?'доступ обычного приложения':'права администратора'}`,connection:'Объяснение конкретного решения о маршрутизации.',exits:'Выход может спать, пока общий TUN обрабатывает остальной трафик.',settings:'Общие настройки для VPN и экспертного режима.',protection:'Что защищено при отказе выхода и при остановке обработчика.',updates:'Обновления из репозитория LerNET на GitHub.'};return map[screen]||screens.find(x=>x.id===screen).description;}
 function pageActions(){if(['network','adapters','programs','system-routes','dns','filters','device','system-events','changes','sources'].includes(screen))return btn('Обновить','refresh','primary','swap')+link('report','Отчёт','','download');if(screen==='profiles')return link('import','Добавить','primary','plus');if(screen==='traffic')return btn('Пауза','pause','','pause');if(screen==='schema'||screen==='routes-list')return link('test-route',mobile?'Путь':'Проверить путь','','search');if(screen==='exits')return link('import','Добавить профиль','','plus');if(screen==='profile')return link('profile-edit','Изменить','','edit');return '';}
 function loading(){return `${notice('Собираем доступные данные','Можно перейти в другой раздел. Настройки сети не изменяются.','','clock')}<div class="loading-skeleton"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div class="actions">${btn('Отменить','cancel-loading')}</div>`;}
 function empty(){return `<div class="empty"><div class="large-icon">${icon('folder')}</div><h2>${['profiles','import-review','folder'].includes(screen)?'Пока нет профилей':'Пока нет данных'}</h2><p>${screen==='traffic'?'Здесь появятся соединения после включения обработки трафика.':'Начните с добавления профиля или обновите доступные данные.'}</p>${link(['profiles','folder'].includes(screen)?'import':'expert','Начать','primary','plus')}</div>`;}
 function renderPage(){return (pages[screen]||(()=>empty()))();}
 function probe(){return `<div class="probe-grid"><div><small>Сервер TLS</small><strong class="green">Отвечает</strong><span class="green">58 мс</span><small>Рукопожатие до узла</small></div><div><small>Через туннель</small><strong class="${state==='blocked'?'red':'green'}">${state==='blocked'?'Не отвечает':'Доступен'}</strong><span class="${state==='blocked'?'red':'green'}">${state==='blocked'?'—':'124 мс'}</span><small>HTTPS через выбранный выход</small></div></div>`;}
 function profileCard(name,selected=false,folder=false){return `<article class="profile-card ${selected?'selected':''} ${folder?'folder':''}" data-search="${name.toLowerCase()}"><div class="inline"><a class="profile-title row-link" href="#${folder?'folder':'profile'}">${appIcon(folder?'folder':'server')}<span><strong>${name}</strong>${folder?` <span class="chip good" title="Автоматическая смена профиля включена">Авто</span>`:''}<small style="display:block">${folder?'2 профиля · маршрут папки':'VLESS · TLS · XHTTP'}</small></span></a>${ib('arrows','probe',folder?'Проверить папку':'Проверить профиль')}${ib('more',folder?'folder-menu':'profile-menu','Другие действия')}</div>${folder?'':probe()}</article>`;}
 function ruleList(){return `<div class="route-rule yellow"><div class="inline"><strong>01 · Мессенджеры</strong>${chip('Общий канал','','portal')}</div><p>Telegram или Signal → папка «Германия»</p><div class="pill-list">${chip('При отказе: запрет','red','lock')}${chip('Запуск по запросу','','moon')}${link('rule','Изменить','small','edit')}</div></div><div class="route-rule yellow"><div class="inline"><strong>02 · Нужные сайты</strong>${chip('Общий канал','','portal')}</div><p>Домен example.org → та же папка «Германия»</p><div class="pill-list">${link('exit-detail','Связи канала','small','portal')}</div></div><div class="route-rule"><strong>03 · Ресурсы компании</strong><p>Сеть 10.20.0.0/16 → корпоративный выход</p><div class="pill-list">${chip('Требуется настройка','yellow')}${link('target-picker','Выбрать выход','small')}</div></div><div class="route-rule red"><strong>04 · Фоновая телеметрия</strong><p>Домен telemetry.example → запрет</p></div><div class="route-rule"><strong>Иначе</strong><p>Напрямую · применяется только к трафику, который не совпал выше</p></div>`;}
 const networkIds=['network','adapters','programs','system-routes','dns','filters','device','system-events','changes','sources'];
 function networkNav(){return `<nav class="network-nav" aria-label="Разделы анализа">${networkIds.map(id=>`<a href="#${id}" class="${screen===id?'active':''}" ${screen===id?'aria-current="page"':''}>${screens.find(x=>x.id===id).title}</a>`).join('')}<select aria-label="Раздел анализа" data-action="network-select">${networkIds.map(id=>`<option value="${id}" ${screen===id?'selected':''}>${screens.find(x=>x.id===id).title}</option>`).join('')}</select></nav>`;}
 const pages={
  welcome:()=>`<div class="welcome"><div class="large-icon">${icon('route')}</div><h1>Ваша сеть.<br>Понятные правила.</h1><p>Подключайтесь к VPN как обычно — или выбирайте путь для отдельных приложений в экспертном режиме.</p><div class="two">${panel('Просто подключиться',`<p>Выберите профиль. LerNET следит за реальной работой туннеля и восстанавливает связь.</p><div class="actions">${link('import','Добавить профиль','primary','plus')}</div>`)}${panel('Управлять сетью',`<p>Пропускайте обычный трафик напрямую. Для нужных приложений задайте VPN, запрет или отдельный выход.</p><div class="actions">${link('permission','Настроить экспертный режим','','route')}</div>`)}</div>${help('Всё начинается с вашего решения','Само открытие экспертной вкладки не включает TUN. Обработка трафика начинается только после нажатия «Включить».')}</div>`,
  permission:()=>`<div class="wide-narrow">${panel(mobile?'Разрешить обработку трафика':'Разрешить создание TUN',`<div class="large-icon">${icon('shield')}</div><p>${mobile?'Android покажет системный запрос на VPN-подключение LerNET. Одновременно в этом профиле устройства работает один VPN.':'Windows покажет запрос прав администратора. Они нужны для виртуального адаптера и маршрутов устройства.'}</p><div class="checklist"><div>${icon('check')}Обычный трафик по умолчанию идёт напрямую</div><div>${icon('check')}Защищённые ветки используют выбранные выходы</div><div>${icon('check')}Отчёт и история хранятся локально</div></div><div class="actions">${btn(mobile?'Разрешить VPN':'Запросить права','grant','primary','shield')}${link('vpn','Пока обычный VPN')}</div>`)}${panel('Если разрешение не получено',`<p>${mobile?'Останутся доступными профили, редактор схемы и доступный Android анализ. Обработка всего трафика не включится.':'Останутся доступными профили, редактор и обычный прокси. Предпочтительный режим VPN будет сохранён.'}</p>${help('После получения разрешения','LerNET предложит продолжить включение. Выбор вкладки сам по себе не запускает обработку.')}`)}</div>`,
  conflict:()=>`${notice('Другой канал может влиять на подключение',mobile?'Android сообщает о действующем VPN. Владельца этой сети система не раскрыла.':'Найден действующий виртуальный адаптер и локальный DNS, связанные с другим сетевым клиентом.','warning','alert')}<div class="two">${panel('Что подтверждено',kv([['Адаптер',mobile?'VPN · владелец недоступен':'Example VPN Tunnel · подключён'],['Маршрут',mobile?'Системные подробности недоступны':'0.0.0.0/1 → интерфейс 23'],['DNS',mobile?'Видимые настройки текущей сети':'127.0.0.1 · служба на порту 53'],['Источник',mobile?'ConnectivityManager':'Get-NetRoute + локальные слушатели']])+help('Почему это важно','При отключении стороннего клиента его DNS или фильтры могут продолжать влиять на доступ. Один признак не доказывает неисправность.'))}${panel('Безопасный порядок',`<div class="flow-steps">${step(1,'Сохранить снимок','Запомнить состояние перед изменением.')}${step(2,'Отключить чужой VPN его средствами','LerNET не останавливает чужие службы автоматически.')}${step(3,'Повторить анализ','Сравнить маршруты, DNS и доступность.')}</div><div class="actions">${link('changes','Сравнить снимки','primary')}${link('network','Открыть доказательства')}</div>`)}</div>`,
  vpn:()=>`<div class="wide-narrow"><div class="stack"><section class="panel connection-card"><div class="connection-top"><div><small>Ваше подключение</small><h2 class="connection-title">${state==='off'?'Готово к подключению':state==='blocked'?'Туннель не отвечает':state==='waking'?'Подключаемся':'Подключено'}</h2><p>Германия-2 · папка «Германия»</p><div class="pill-list">${chip('Полный VPN','accent')}${chip('Автосмена','good','swap')}${link('schema','Маршрут','small','route')}</div></div><button class="power ${state==='off'?'off':state==='blocked'?'warning':''}" data-action="connect" aria-label="${state==='off'?'Подключиться':'Отключиться'}">${icon('power')}</button></div><div class="metrics"><div class="metric"><small>Через туннель</small><strong class="green">${state==='blocked'?'—':'124 мс'}</strong></div><div class="metric"><small>Получено</small><strong>${state==='off'?'0 Б':'42,8 МБ'}</strong></div><div class="metric"><small>Соединения</small><strong>${state==='off'?'0':'18'}</strong></div></div></section>${panel('Проверка связи',probe()+`<div class="actions">${btn('Проверить связь','probe','','arrows')}</div><small>Ответ сервера подтверждает доступ до узла. Проверка через туннель подтверждает работу выхода.</small>`)}${panel('Режим подключения',`<div class="segmented"><button class="selected" data-action="select-vpn">Полный VPN</button><button data-action="select-proxy">Прокси</button></div><p style="margin-top:12px">Весь трафик устройства идёт по маршруту выбранного профиля.</p>`)}</div><div class="stack">${panel('Выбранный профиль',`${row('Германия-2','VLESS · TLS · XHTTP','server',link('profiles','Сменить','small'))}${row('Германия','Маршрут папки · 2 профиля','folder',link('folder','Открыть','small'))}`)}${panel('Связь восстанавливается автоматически',`<p>Если сервер отвечает, а туннель перестал передавать запросы, LerNET повторно подключит профиль или выберет другой в папке.</p>${help('Последняя проверка','12:41:08 · HTTPS через профиль · успешный ответ за 124 мс')}`)}</div></div>`,
  profiles:()=>`<div class="toolbar"><input class="search" type="search" aria-label="Поиск профиля" placeholder="Найти папку или профиль" data-search-input>${btn('Проверить все','probe','','arrows')}</div><div class="split-profiles"><div class="profile-list">${profileCard('Германия',false,true)}<div style="padding-left:15px">${profileCard('Германия-1')}${profileCard('Германия-2',true)}</div>${profileCard('Нидерланды',false,true)}${profileCard('Личный профиль')}</div><div class="stack">${panel('Германия-2',`<div class="inline">${chip('Выбран','accent')}${chip('В папке «Германия»')}</div>${probe()}${actions(link('profile','Параметры')+link('vpn','Подключение','primary','power'))}`)}${panel('Как устроена папка',`<p>Настройте смену профилей один раз. Для повседневной проверки доступна кнопка с двумя стрелками.</p>${help('Перемещение','Зажмите свободную часть карточки. Призрак следует за пальцем или мышью; кнопки продолжают выполнять свои действия.')}`)}</div></div>`,
  profile:()=>`<div class="two">${panel('Германия-2',`${kv([['Протокол','VLESS'],['Защита','TLS'],['Транспорт','XHTTP'],['Папка',link('folder','Германия','small')],['Адрес сервера','vpn.example.net:443'],['Идентификатор','•••••••• · скрыт']])}${probe()}${actions(btn('Проверить','probe','','arrows')+link('vpn','Выбрать профиль','primary'))}`)}${panel('Маршрут и переносимость',`<p>В обычном VPN действует маршрут папки «Германия». В экспертной схеме цель явно определяет, какое дерево используется.</p>${row('Маршрут папки','Доступен на этом устройстве','route',link('schema','Открыть','small'))}${row('Ветка Android',`Сохранена, ${mobile?'активна':'неактивна на Windows'}`,'laptop',chip(mobile?'Активна':'Другая платформа',mobile?'good':'yellow'))}${actions(link('import','Экспорт / импорт','','file'))}`)}</div>`,
  'profile-edit':()=>`${panel('Параметры подключения',`<form class="form" data-form="profile">${field('profile-name','Название','Германия-2')}${select('profile-folder','Папка',['Германия','Нидерланды','Без папки'])}<div class="two">${field('profile-host','Сервер','vpn.example.net')}${field('profile-port','Порт','443','1–65535','number')}</div>${select('profile-protocol','Протокол',['VLESS','Shadowsocks','Trojan','SOCKS / HTTP — внешний выход'])}${field('profile-secret','Идентификатор / пароль','demo-secret','Секрет скрывается в журнале и диагностическом отчёте.','password')}<div class="two">${select('profile-tls','Защита',['TLS','REALITY'])}${select('profile-transport','Транспорт',['XHTTP','TCP','WebSocket'])}</div>${help('Сохранение работающего профиля','Новая версия проверяется до применения. При ошибке остаётся действующий выход и сохранённый черновик.')}${actions(link('profile','Отмена')+'<button class="btn primary" type="submit">Сохранить профиль</button>')}</form>`)}`,
  folder:()=>`<div class="two">${panel('Профили папки',profileCard('Германия-1')+profileCard('Германия-2',true)+actions(link('import','Добавить в папку','primary','plus')))}${panel('Германия',`${kv([['Выбор выхода','Предпочтительный, затем доступный'],['Предпочтительный','Германия-2'],['Автосмена','Включена'],['Маршрут','Общий для папки']])}${row('Политика выбора','Меняется отдельно от проверки связи','swap',link('folder-policy','Настроить','small'))}${row('Схема папки','Сохранено 4 правила','route',link('schema','Открыть','small'))}${help('Добавление на ходу','Новый профиль становится кандидатом после проверки. Общий TUN и соединения других веток сохраняются.')}`)}</div>`,
  import:()=>panel('Добавить подключение',`<div class="segmented"><button class="selected" data-action="import-link">Ссылка / JSON</button><button data-action="choose-file">Файл</button>${mobile?'<button data-action="qr">QR</button>':''}</div><form class="form" data-form="import" style="margin-top:22px"><div class="field"><label for="import-text">Ссылка или содержимое файла</label><textarea id="import-text" placeholder="VLESS-ссылка, JSON ядра или архив LerNET"></textarea><small>Архив с другой платформы сохраняет её ветки. Доступные этому устройству правила будут показаны до добавления.</small></div><input type="file" id="import-file" accept=".json,.txt,.lernet" hidden>${select('import-folder','Добавить в папку',['Германия','Нидерланды','Без папки'])}${actions(btn('Открыть пример','sample-import')+'<button class="btn primary" type="submit">Проверить и продолжить</button>')}</form>`),
  'import-review':()=>`${notice('Готово к добавлению','Исходные данные ещё не применены. Проверьте состав и совместимость.','good','check')}<div class="two">${panel('Что добавится',row('Германия-3','Профиль VLESS · папка «Германия»','server')+row('Маршрут папки','2 условия · 1 общий канал','route')+kv([['Версия архива','LerNET · схема данных 2'],['Секреты','В приватном хранилище'],['Совпадения','Существующие профили не заменяются']]))}${panel('Совместимость',`${notice('Одна ветка неактивна',mobile?'Windows-процесс Telegram.exe сохранится, но не будет условием Android.':'Android-пакет org.telegram.messenger сохранится, но не будет условием Windows.','warning')}<p>Можно сразу создать соответствующую ветку для этого устройства. При экспорте исходная ветка остаётся в архиве.</p>${actions(btn('Добавить и применить','import-confirm','primary')+link('import','Назад'))}`)}</div>`,
  expert:()=>`<div class="wide-narrow"><div class="stack"><section class="panel connection-card"><div class="connection-top"><div><small>Обработка сети устройства</small><h2 class="connection-title">${state==='off'?'Экспертный режим выключен':'Общий TUN работает'}</h2><p>Обычный трафик — напрямую.<br>Выбранные ветки — по вашим правилам.</p><div class="pill-list">${chip('Схема №'+revision,'accent','route')}${chip('Без обхода для 2 веток','good','lock')}</div></div><button class="power ${state==='off'?'off':''}" data-action="expert-toggle" aria-label="${state==='off'?'Включить экспертный режим':'Выключить экспертный режим'}">${icon('power')}</button></div><div class="metrics"><div class="metric"><small>Работают</small><strong>${state==='off'?'0 выходов':'1 выход'}</strong></div><div class="metric"><small>Спят</small><strong>2 выхода</strong></div><div class="metric"><small>Заблокировано</small><strong>4 запроса</strong></div></div></section>${panel('Ваша схема',`<div class="route-strip"><span class="step">Приложения</span>${icon('arrow')}<span class="step">Правила</span>${icon('arrow')}<span class="step">Выбранный выход</span></div><p>Мессенджеры используют папку «Германия». Остальной интернет идёт напрямую.</p>${actions(link('routes-list','Списком')+link('schema','Открыть схему','primary','route'))}`)}${panel('Сетевые выходы',exitRows())}</div><div class="stack">${panel('Что произошло',row('Telegram разбудил выход','12:40 · Германия-2 готов за 420 мс','bolt',link('connection','Путь','small'))+row('Телеметрия остановлена','12:39 · правило «Фоновые запросы»','lock',link('traffic','Трафик','small')))}${panel('Проверить устройство',`<p>Посмотрите действующие адаптеры, DNS и возможное влияние других сетевых клиентов.</p><div class="actions">${link('network','Сеть устройства','','globe')}</div>`)}${panel('Защита при сбое',`<p>Запрет прямого доступа для ветки и защита при падении общего TUN имеют разные гарантии.</p><div class="actions">${link('protection','Посмотреть гарантии','','shield')}</div>`)}</div></div>`,
  schema:()=>`${state==='empty'?empty():`<div class="toolbar"><select class="scope-select" aria-label="Чья схема редактируется"><option>Устройство · экспертная схема</option><option>Папка · Германия</option><option>Профиль · Германия-2</option></select><div class="segmented"><a class="selected" href="#schema">${icon('route')} ${mobile?'':'Схема'}</a><a href="#routes-list">Списком</a></div></div><div class="draft-bar"><div><strong>${dirty||state==='draft'?'Есть несохранённые изменения':(mobile?'Схема №':'Работает схема №')+revision}</strong><p class="muted" style="font-size:12px;margin-top:3px">${dirty||state==='draft'?'Общий TUN продолжает использовать предыдущую версию.':'Редактирование создаёт черновик. Применение выполняется отдельно.'}</p></div><div class="actions">${btn(mobile?'Отмена':'Отменить','discard','small')}${btn(mobile?'Применить':'Сохранить и применить','apply','primary small','check')}</div></div>${mobile?'<div class="toolbar"><select aria-label="Показать ветку схемы" id="graph-branch"><option>Мессенджеры → Германия</option><option>Нужные сайты → Германия</option><option>Телеметрия → запрет</option></select></div>':''}<div class="graph-wrap" id="graph-wrap"><div class="graph" id="graph"><svg class="edges" aria-hidden="true"></svg></div></div><div class="graph-caption"><span>${icon('portal')} Один общий канал · 2 входящие ветки</span><div class="graph-tools">${btn('−','zoom-out','small')}${btn('100%','zoom-reset','small')}${btn('+','zoom-in','small')}${link('rule','Правило','small','plus')}</div></div><div class="actions">${link('exit-detail','Кто связан с каналом?','','portal')}${link('test-route','Проверить путь без запроса','','search')}</div>`}`,
  'routes-list':()=>`<div class="toolbar"><select class="scope-select" aria-label="Чья схема редактируется"><option>Устройство · экспертная схема</option><option>Папка · Германия</option><option>Профиль · Германия-2</option></select><div class="segmented"><a href="#schema">Схема</a><a href="#routes-list" class="selected">Списком</a></div></div>${ruleList()}${actions(link('rule','Добавить правило','','plus')+btn('Сохранить и применить','apply','primary','check'))}`,
  rule:()=>`<div class="wide-narrow">${panel('Мессенджеры',`<form class="form" data-form="rule">${field('rule-name','Название правила','Мессенджеры')}${select('rule-join','Совпадение условий',['Хотя бы одно (ИЛИ)','Все условия (И)'])}<div class="field"><label>Приложения</label><div class="pill-list"><span class="pill">${icon('laptop')}Telegram${ib('close','remove-pill','Убрать Telegram')}</span><span class="pill">Signal</span></div>${link('application-picker','Выбрать приложения','small','plus')}</div><div class="field"><label for="rule-domain">Домен или шаблон</label><div class="entry-line"><input id="rule-domain" placeholder="Например: *.example.org"><button class="commit-check" type="button" data-action="commit-pattern" aria-label="Добавить условие">${icon('check')}</button></div><small>Кнопка с галочкой добавляет значение независимо от клавиатуры.</small><div id="patterns" class="pill-list"></div></div><div class="divider"></div>${select('rule-target','Куда отправлять',['Папка · Германия','Профиль · Германия-2','Напрямую','Запретить','Внешний выход'])}${link('target-picker','Выбрать другую цель','small','route')}${select('rule-failure','Если цель недоступна',['Запретить прямой доступ','Разрешить прямой доступ'])}${toggle('rule-protect','Не разрешать обход внутри дочерней схемы','Прямой выход в дереве профиля не отменяет защиту этой ветки.')}${actions(link('schema','Отмена')+'<button class="btn primary" type="submit">Сохранить в черновик</button>')}</form>`)}${panel('Как правило сработает',`<div class="flow-steps">${step(1,'Telegram или Signal','Определили приложение и проверили условия.')}${step(2,'Общий канал «Мессенджеры»','Обе ветки используют одну цель и одно состояние.')}${step(3,'Папка «Германия»','Выбрали доступный профиль согласно политике папки.')}${step(4,'Если не удалось','Соединение прекращается с объяснением. Прямого обхода нет.')}</div>${link('test-route','Проверить пример','','search')}`)}</div>`,
  'application-picker':()=>panel(mobile?'Приложения устройства':'Программы Windows',`<div class="segmented"><button class="selected" data-action="apps-all">Установленные</button><button data-action="apps-running">${mobile?'С активным трафиком':'Запущенные'}</button>${mobile?'':btn('Указать .exe','choose-exe','small')}</div><div class="toolbar" style="margin-top:17px"><input type="search" aria-label="Поиск приложения" placeholder="Название${mobile?' или пакет':' или исполняемый файл'}" data-search-input></div><div id="app-list">${[['Telegram','telegram',mobile?'org.telegram.messenger':'Telegram.exe'],['Firefox','firefox',mobile?'org.mozilla.firefox':'firefox.exe'],['Signal','shield',mobile?'org.thoughtcrime.securesms':'Signal.exe'],['Корпоративный клиент','laptop',mobile?'com.example.company':'CompanyClient.exe']].map(([name,ico,id])=>`<label class="row" data-search="${name.toLowerCase()} ${id.toLowerCase()}"><input type="checkbox" ${name==='Telegram'?'checked':''} style="accent-color:var(--accent);width:18px;height:18px">${appIcon(ico)}<span class="grow"><strong>${name}</strong><small style="display:block">${id}</small></span>${chip(name==='Telegram'?'Запущено':'Установлено')}</label>`).join('')}</div><input type="file" id="exe-file" accept=".exe" hidden>${help('Не удалось определить владельца','Соединение не присваивается похожему приложению по догадке. Для него можно создать отдельное правило по адресу или безопасному действию по умолчанию.')}${actions(link('rule','Отмена')+btn('Выбрать','select-apps','primary'))}`),
  'target-picker':()=>panel('Куда отправлять трафик',`<div class="chooser-list">${chooser('Напрямую','Обычная сеть устройства','globe','rule')}${chooser('Запретить','Соединение не покидает устройство','lock','rule')}${chooser('Папка · Германия','2 профиля · выбор и автосмена','folder','folder-policy')}${chooser('Профиль · Германия-2','VLESS · собственное дерево правил','server','rule')}${chooser('Корпоративный выход','SOCKS / HTTP или поддерживаемый провайдер','laptop','external-exit')}</div>${help('Корпоративный VPN и SSTP','Внешний выход должен быть привязан к нужному интерфейсу и не перехватывать общий маршрут. Доступность провайдера показывается отдельно для каждой платформы.')}${actions(link('rule','Назад'))}`),
  'external-exit':()=>`<div class="two">${panel('Корпоративный выход',`<form class="form" data-form="external">${field('external-name','Название','Компания')}${select('external-provider','Способ подключения',['Готовый SOCKS / HTTP','Корпоративный интерфейс','SSTP — после проверки адаптера'])}${field('external-host','Адрес сервиса','proxy.company.example')}${field('external-port','Порт','1080','','number')}${field('external-user','Имя пользователя','demo-user')}${field('external-secret','Пароль','','Хранится в приватном хранилище, не в отчёте.','password')}${field('external-networks','Ресурсы компании','10.20.0.0/16','Отправляем только явно выбранные сети, а не весь интернет.')}${select('external-interface','Путь к провайдеру',mobile?['Защищённый внешний сокет LerNET','Доступный транспорт внутри VpnService']:['Корпоративный VPN-интерфейс','Через выбранный сетевой адаптер'])}${select('external-failure','При недоступности',['Запретить доступ','Явно разрешить прямой путь'])}${actions(link('target-picker','Отмена')+'<button type="submit" class="btn primary">Сохранить выход</button>')}</form>`)}${panel('Возможности провайдера',`${row('SOCKS / HTTP','Использовать готовый прокси-сервис','server',chip('Цель доступна','good'))}${row('SSTP','Подключение через отдельный адаптер провайдера','shield',chip('Требует проверки','yellow'))}${help('SSTP не становится прокси автоматически',mobile?'Нужен SSTP-транспорт внутри LerNET VpnService. Запуск другого VPN-приложения не создаёт выход для этой схемы.':'Нужен контролируемый корпоративный интерфейс и привязанный к нему выход. Его маршруты не должны забирать весь трафик у LerNET.')}<details class="accordion"><summary>Проверка перед включением</summary><div>TLS и сертификат, доступ до сервера вне собственного TUN, интерфейс назначения, IPv4/IPv6, TCP/UDP и политика отказа. Неподдерживаемая возможность сохраняется с объяснением.</div></details>` )}</div>`,
  'folder-policy':()=>`<div class="two">${panel('Выбор профиля',`<form class="form" data-form="policy">${radio('folder-choice','preferred','Предпочтительный, затем доступный','Сначала Германия-2. При отказе пробуем следующий доступный.',true)}${radio('folder-choice','fastest','Наименьшая задержка','Среди кандидатов с подтверждённой работой выхода.')}${select('preferred','Предпочтительный профиль',['Германия-2','Германия-1'])}${toggle('folder-swap','Автоматическая смена','Если активный выход перестал передавать запросы.')}${select('folder-failure','Когда все профили недоступны',['Запретить для этой ветки','Разрешить прямой доступ'])}${actions(link('folder','Отмена')+'<button class="btn primary" type="submit">Сохранить политику</button>')}</form>`)}${panel('Проверки и стабильность',`${field('score-age','Срок годности измерения, минуты','5','Просроченная оценка требует проверки при выборе.','number')}${field('cooldown','Пауза повторного выбора, секунды','20','Помогает избежать непрерывного переключения между близкими результатами.','number')}${help('Спящие кандидаты','Не поддерживаем постоянный пинг всех выходов. При пробуждении проверяем ограниченный набор кандидатов; старые оценки помечаем как старые.')}${row('Запуск и сон','Отдельная политика активности выхода','moon',link('lifecycle','Настроить','small'))}`)}</div>`,
  lifecycle:()=>`<div class="two">${panel('Когда поднимать выход',`<form class="form" data-form="lifecycle">${radio('startup','demand','По первому запросу','Спит, пока ни одно соединение не пришло в эту ветку.',true)}${radio('startup','eager','Сразу при включении режима','Подходит для постоянно используемых выходов.')}${field('idle-minutes','Усыплять после неактивности, минут','15','Отсчёт начинается после последней пользовательской активности.','number')}${toggle('keep-live','Сохранять открытые соединения','Тихое живое соединение не обрывается ради таймера.')}${select('startup-failure','Если пробуждение не удалось',['Запретить соединение','Следовать разрешённому прямому fallback'])}${actions(link('exit-detail','Отмена')+'<button class="btn primary" type="submit">Сохранить</button>')}</form>`)}${panel('Что считается активностью',`${row('Пользовательские данные','Продлевают время работы выхода','activity',chip('Да','good'))}${row('Проверка доступности LerNET','Не продлевает таймер и не будит спящий выход','arrows',chip('Нет'))}${row('Первое соединение','Ожидает готовность в пределах заданного срока','clock')}${help('Сон — понятное состояние','На схеме будет видно: «Спит до первого запроса» или «Можно усыпить через 14:32». При активном соединении таймер не обещает остановку.')}`)}</div>`,
  exits:()=>`${panel('Выходы общей схемы',exitRows())}<div class="two" style="margin-top:18px">${panel('Общий TUN',`<div class="inline">${chip('Работает','good','check')}<span class="muted">Не перезапускается при смене выхода</span></div><div class="metrics"><div class="metric"><small>Напрямую</small><strong>12</strong></div><div class="metric"><small>Через VPN</small><strong>6</strong></div><div class="metric"><small>Ожидают</small><strong>${state==='waking'?'2':'0'}</strong></div></div>`)}${panel('Добавить без остановки',`<p>Профиль проходит проверку и добавляется в папку. Новые соединения могут использовать его после успешного применения.</p><div class="actions">${link('import','Добавить профиль','primary','plus')}</div>`)}</div>`,
  'exit-detail':()=>`<div class="wide-narrow">${panel('Общий канал · Мессенджеры',`${kv([['Цель','Папка · Германия'],['Выбранный профиль','Германия-2'],['Состояние',chip(state==='off'?'Спит':state==='blocked'?'Недоступен':'Работает',state==='blocked'?'red':'good')],['Открытых соединений','6'],['Последние данные','12:41:02'],['Сон','После закрытия соединений и 15 минут тишины']])}<div class="divider"></div><h3>Входящие ветки</h3>${row('Мессенджеры','Telegram или Signal','portal',link('rule','Открыть','small'))}${row('Нужные сайты','Домен example.org','portal',link('schema','На схеме','small'))}${actions(btn('Пробудить','wake','','bolt')+link('lifecycle','Запуск и сон')+link('folder-policy','Выбор профиля'))}`)}${panel('Почему выбран этот профиль',`<div class="flow-steps">${step(1,'Сработало правило «Мессенджеры»','Получен запрос Telegram.')}${step(2,'Германия-2 — предпочтительный','Успешная проверка через выход: 124 мс.')}${step(3,'Германия-1 — резервный','Не открываем лишние подключения без необходимости.')}</div>${help('Один физический канал','Обе входящие ветки используют этот объект. Переименование не создаёт новый канал: связь определяется его идентификатором.')}`)}</div>`,
  redirect:()=>panel('Замена назначения',`<form class="form" data-form="redirect"><div class="two">${field('redirect-from','Если адрес назначения','old.internal.example')}${field('redirect-from-port','Порт назначения','8080','','number')}</div><div class="inline">${icon('arrow')}<strong>Отправлять на</strong></div><div class="two">${field('redirect-to','Новый адрес','new.internal.example')}${field('redirect-to-port','Новый порт','8443','','number')}</div>${select('redirect-out','Затем использовать выход',['Корпоративный выход','Папка · Германия','Напрямую'])}${select('redirect-net','Протокол',['TCP','UDP','TCP и UDP'])}${help('Что именно меняется','Меняется адрес и порт назначения. HTTPS по-прежнему проверяет имя и сертификат; перенаправление само по себе не исправляет их несовпадение. Изменение исходного IP — отдельная возможность провайдера.')}${actions(link('schema','Отмена')+'<button class="btn primary" type="submit">Добавить в черновик</button>')}</form>`),
  'test-route':()=>`<div class="two">${panel('Проверить решение схемы',`<form class="form" data-form="test-route">${select('test-app','Приложение',['Telegram','Firefox','Неизвестный владелец'])}${field('test-host','Адрес назначения','example.org')}${field('test-port','Порт','443','','number')}${select('test-net','Протокол',['TCP','UDP'])}${select('test-version','Версия схемы',['Черновик','Активная №16'])}${help('Без сетевого запроса','Это локальная проверка условий. Она объясняет выбор пути, но не проверяет доступность сервера.')}${actions('<button class="btn primary" type="submit">Показать путь</button>')}</form>`)}${panel('Результат',`<div id="route-test-result"><div class="flow-steps">${step(1,'Приложение Telegram','Совпало с правилом №1 «Мессенджеры».')}${step(2,'Общий канал','Цель: папка «Германия».')}${step(3,'Политика отказа','При отсутствии доступного профиля: запрет.')}</div>${chip('Прямого обхода нет','good','lock')}</div>`)}</div>`,
  traffic:()=>`<div class="toolbar"><input class="search" type="search" aria-label="Поиск соединений" placeholder="Приложение, домен или адрес" data-search-input><div class="segmented"><button class="selected" data-action="traffic-all">Все</button><button data-action="traffic-blocked">Запреты</button><button data-action="traffic-unknown">Неизвестные</button></div></div><div class="panel table-card table-wrap"><table class="traffic-table"><thead><tr><th>Приложение</th><th>Назначение / путь</th><th>Объём</th><th></th></tr></thead><tbody>${trafficRows()}</tbody></table></div>${help('Как оценивать фоновый запрос','Показываем приложение, назначение и правило. Сам по себе неизвестный домен не означает угрозу. Если имя или владелец не определены, так и указываем.')}`,
  connection:()=>`<div class="wide-narrow">${panel('Telegram → example.org',`<div class="inline">${appIcon('telegram','T')}${chip('TCP · 443')}${chip(state==='blocked'?'Заблокировано':'Через VPN',state==='blocked'?'red':'good')}</div><div class="divider"></div><div class="flow-steps">${step(1,'Приложение','Telegram · '+(mobile?'org.telegram.messenger':'Telegram.exe · PID 4208'))}${step(2,'Условие совпало','Правило «Мессенджеры» · активная схема №16.')}${step(3,'Общий канал','Связан с двумя ветками; использует папку «Германия».')}${step(4,'Выбран выход','Германия-2 · предпочтительный · пробуждён по запросу.')}${step(5,'Решение','Разрешено через выбранный выход. При его отказе прямой доступ запрещён.')}</div>${actions(link('rule','Открыть правило')+link('exit-detail','Состояние выхода','primary'))}`)}${panel('Что известно о соединении',`${kv([['Назначение','203.0.113.24:443'],['Домен','example.org · из доступных метаданных'],['Отправлено','18,2 КБ'],['Получено','64,1 КБ'],['Начало','12:40:56'],['Владелец','Подтверждён платформой']])}${help('Граница наблюдения','Содержимое HTTPS не раскрывается. Домен может быть недоступен при шифровании DNS или метаданных. Объяснение относится к решению LerNET, а не к намерению приложения.')}`)}</div>`,
  events:()=>panel('Последние события',timeline([['12:41','Схема №16 продолжает работать','Трафик остальных веток не затронут.'],['12:40','Выход проснулся по запросу Telegram','Германия-2 · готов за 420 мс.'],['12:39','Запрос остановлен правилом','telemetry.example · прямой доступ запрещён.'],['12:34','Нидерланды перешёл в сон','Нет открытых соединений; 15 минут без пользовательских данных.'],['12:20','Сеть изменилась','Проверены активные выходы; старые оценки доступности помечены устаревшими.']])),
  logs:()=>panel('Журнал LerNET',`<div class="toolbar"><select aria-label="Фильтр журнала" style="width:auto"><option>Все этапы</option><option>Ошибки</option><option>Проверки связи</option><option>Выходы</option></select>${btn('Сохранить журнал','download-log','','download')}</div><div class="log">${[['12:41:08','health','Германия-2 · HTTPS через выход · 124 мс · ответ 204'],['12:40:56','wake','exit=Germany · requested_by=rule-1 · ждут 2 соединения'],['12:40:56','connect','TCP → TLS → транспорт → готов · 420 мс'],['12:38:04','probe','Германия-1 · этап TLS · срок ожидания 30000 мс'],['12:38:04','cause','Timeout · ответа на рукопожатие нет · сетевой источник отказа не установлен'],['12:38:04','policy','Следующий кандидат: Германия-2 · прямой fallback запрещён'],['12:34:00','sleep','Нидерланды · idle=15m · active_flows=0']].map(([t,s,m])=>`<div class="log-line"><span class="log-time">${t}</span> <span class="log-stage">[${s}]</span> ${m}</div>`).join('')}</div>${help('Секреты удаляются до записи','Пароли, ключи и ссылки подключения не попадают в журнал. Понятная причина сохраняется вместе с этапом и длительностью.')}`),
  network:()=>`${networkNav()}<div class="wide-narrow"><div class="stack">${panel('Путь обычного интернета',`<div class="route-strip"><span class="step">Устройство</span>${icon('arrow')}<span class="step">${mobile?'Wi-Fi':'Wi-Fi · интерфейс 7'}</span>${icon('arrow')}<span class="step">Шлюз 192.168.1.1</span></div><p>Это базовый путь сети. Включённый TUN применяет ваши правила поверх него.</p>${actions(link('system-routes','Разобрать маршрут','','route'))}`)}${panel('На что обратить внимание',`${notice('DNS зависит от локальной службы','В настройке указан 127.0.0.1. Ответы возможны, пока на устройстве работает соответствующий DNS-сервис.','warning')}<div class="evidence"><strong>Основание вывода</strong>${mobile?'Из видимых LinkProperties получен DNS 127.0.0.1. Полный перечень чужих слушателей Android недоступен.':'Адаптер Wi-Fi → DNS 127.0.0.1; найден UDP-слушатель :53. Связь с программой показана по владельцу PID.'}</div>${actions(link('dns','Объяснение и источник','small'))}`)}${panel('Записи отключённых адаптеров',`<p>Служебные multicast и broadcast записи исключены из предупреждения. Подозрителен путь нужного трафика, если он действительно выбирается через отключённый интерфейс.</p>${actions(link('adapters','Посмотреть адаптеры','small'))}`)}</div><div class="stack">${panel('Внешний адрес',`<p>Внешний сервис ещё не запрашивался.</p>${help('По вашему действию','Сервис определения IP увидит ваш исходящий адрес. До нажатия данные за пределы устройства не отправляются для этого запроса.')}<div class="actions">${btn('Узнать внешний IP','external-ip','','globe')}</div>`)}${panel('Полнота снимка',`${row('Настройки сети','Собраны в 12:41','check',chip('Доступны','good'))}${row('Системные блокировки',mobile?'Android не раскрывает WFP':'Аудит отключён; события не собраны','info',chip('Нет данных','yellow'))}${actions(link('sources','Все источники','small'))}`)}</div></div>`,
  adapters:()=>`${networkNav()}${panel('Интерфейсы устройства',`${row('Wi-Fi','Подключён · 192.168.1.24 · шлюз 192.168.1.1','wifi',chip('Основная сеть','good'))}${row('LerNET TUN','Виртуальный адаптер · общий обработчик','route',chip('LerNET','accent'))}${mobile?'':row('Example VPN Tunnel','Отключён · интерфейс 23 · сохранённые записи','server',chip('Отключён'))}${help('Адаптер — вход в сеть','Wi-Fi ведёт к вашей точке доступа. Виртуальный адаптер передаёт пакеты программе. Само наличие виртуального адаптера не доказывает активный VPN.')}<details class="accordion"><summary>Wi-Fi: адреса, метрика и DNS</summary><div>${kv([['IPv4','192.168.1.24/24'],['IPv6','Доступен · отдельные маршруты'],['MTU','1500'],['Метрика','25'],['DNS','127.0.0.1'],['Источник',mobile?'LinkProperties':'Get-NetAdapter / Get-NetIPConfiguration']])}</div></details>`)}`,
  programs:()=>`${networkNav()}${panel('Кто участвует в работе сети',`${row('LerNET','Наш TUN и выбранные выходы','route',chip('Подтверждено','good'))}${row('Example VPN',mobile?'Владелец активной VPN-сети не раскрыт ОС':'Установленная программа; служба и виртуальный адаптер','shield',chip(mobile?'Ограничено':'Есть признаки','yellow'))}${row('Локальный DNS','Ответы на 127.0.0.1:53','server',chip(mobile?'Владелец недоступен':'PID 3140'))}${help('Установленное ≠ активное','Наличие программы в списке не означает, что она сейчас управляет трафиком. В отчёте отдельно показываются процесс, служба, интерфейс и подтверждающий источник.')}${actions(link('conflict','Проверить возможный конфликт','','alert'))}`)}`,
  'system-routes':()=>`${networkNav()}${panel('Как выбран путь',`<form data-form="system-route" class="form"><div class="entry-line"><input id="route-address" type="text" aria-label="Адрес для проверки маршрута" value="203.0.113.24"><button class="btn primary" type="submit">Показать</button></div></form><div class="route-strip"><span class="step">203.0.113.24</span>${icon('arrow')}<span class="step">LerNET TUN</span>${icon('arrow')}<span class="step">По схеме устройства</span></div>${kv([['Префикс','0.0.0.0/1'],['Интерфейс','LerNET TUN'],['Состояние','Подключён'],['Выбор',mobile?'Видимый маршрут; выбор ОС ограниченно доступен':'Подтверждён IP Helper для этого адреса']])}${help('Почему выбрали этот маршрут','Сначала сравнивается точность префикса, затем применимые метрики. Низкая метрика сама по себе не побеждает более точный маршрут.')}<details class="accordion"><summary>Другие записи, включая служебные</summary><div>224.0.0.0/4 — multicast, 255.255.255.255/32 — broadcast. Это служебные адреса; они не относятся к обычному интернет-запросу.</div></details>`)}`,
  dns:()=>`${networkNav()}<div class="two">${panel('Разрешение имён',`${kv([['Текущая настройка','127.0.0.1'],['Источник',mobile?'LinkProperties сети':'Настройка адаптера Wi-Fi'],['Локальный сервис',mobile?'Недостаточно данных для проверки':'UDP :53 · PID 3140'],['Для защищённой ветки','DNS следует политике выбранного выхода']])}${help('Что означает 127.0.0.1','Устройство спрашивает адреса сайтов у программы на самом себе. Если программа исчезнет, разрешение имён может перестать работать, хотя Wi-Fi остаётся подключён.')}<div class="evidence"><strong>Почему выделено</strong>Настройка зависит от отдельного локального компонента. Это зависимость, а не доказательство поломки.</div>`)}${panel('Системный прокси',`${kv([['Прокси браузерных приложений',mobile?'Зависит от настроек Wi-Fi':'Не задан'],['WinHTTP',mobile?'Не относится к Android':'Прямой доступ'],['PAC',mobile?'Не обнаружен в видимых данных':'Не задан']])}${help('Почему прокси бывают разные','Программы используют разные сетевые библиотеки. Настройка одного прокси не гарантирует, что весь трафик устройства пойдёт через него.')}`)}</div>`,
  filters:()=>`${networkNav()}${mobile?notice('Системные фильтры недоступны','Android не предоставляет обычному приложению полный список чужих фильтров. LerNET показывает только свои решения и доступные признаки.','warning'):''}${panel('Блокировки и фильтры',`${row('Ветка «Фоновая телеметрия»','Решение LerNET · правило №4 · запрос остановлен','lock',chip('Подтверждено','red'))}${mobile?'':row('Сторонний WFP provider','Найден в системе; событие отказа не сопоставлено','shield',chip('Только наличие','yellow'))}${help('Когда можно назвать виновника','Нужны событие блокировки конкретного соединения и соответствующий фильтр той же сессии. Список установленных фильтров без события не доказывает причину.')}${actions(link('system-events','События и доказательства','','clock'))}`)}`,
  device:()=>`${networkNav()}<div class="two">${panel('Доступные возможности',`${row('Обработка TUN','IPv4 / IPv6 · TCP / UDP','route',chip('Доступна','good'))}${row('Приложения',mobile?'Пакеты Android и доступная идентичность UID':'Каталог программ, процессы и пути .exe','laptop',chip('Доступны','good'))}${row('Системные фильтры',mobile?'Полный перечень не раскрывается':'WFP, доступ зависит от прав и источника','shield',chip(mobile?'Недоступны':'Частично','yellow'))}`)}${panel('Сеть и система',`${kv([['Платформа',mobile?'Android 15':'Windows 11'],['Разрешения',mobile?'VpnService · foreground service':'Администратор'],['Подключение','Wi-Fi'],['MTU','1500'],['Корпоративный профиль',mobile?'Отдельный контекст, если существует':'Зависит от установленных провайдеров']])}${help('Показываем пределы доступа','Не заменяем отсутствие данных словом «всё хорошо». Каждая недоступная возможность сохраняет причину.')}`)}</div>`,
  'system-events':()=>`${networkNav()}${panel('События системы',timeline([['12:40','Сеть Wi-Fi подключена',mobile?'Источник: NetworkCallback.':'Источник: WLAN-AutoConfig.'],['12:39','Обновлён основной маршрут','Сопоставлен с новым снимком интерфейсов.'],['12:38','TLS-проверка не завершилась','Событие проверки LerNET; причина не приписана стороннему фильтру.']])+help('Близость по времени — ещё не причина','События складываются в последовательность. Подтверждённая причина отдельно опирается на совпадающее соединение и источник.'))}`,
  changes:()=>`${networkNav()}<div class="toolbar"><span class="chip accent">База · 12:20</span>${icon('arrow')}<span class="chip">Текущий снимок · 12:41</span>${btn('Сделать текущий базой','pin-baseline','','check')}</div>${panel('Изменения',`${row('Появился LerNET TUN','Не было → подключён','route',chip('Добавлено','good'))}${row('Основной маршрут','Wi-Fi → LerNET TUN для выбранных адресов','route',chip('Изменён','accent'))}${row('Локальный DNS','127.0.0.1 → 127.0.0.1','server',chip('Без изменений'))}${help('Сравнение помогает отделить причины','Если сторонний VPN отключили, а DNS остался прежним, это видно здесь. Сравнение не исправляет сеть автоматически.')}${actions(link('report','Сохранить цельный отчёт','','download'))}`)}`,
  sources:()=>`${networkNav()}${panel('Полнота и свежесть',`${row(mobile?'LinkProperties':'Адаптеры и маршруты','Собраны · 12:41:02 · 180 мс','check',chip('Полные','good'))}${row('Владельцы соединений',mobile?'Доступность зависит от UID и версии ОС':'Завершённые процессы могут не определиться','laptop',chip('Частично','yellow'))}${row(mobile?'Чужие VPN-профили':'WFP события',mobile?'Android не раскрывает конфигурации других приложений':'Аудит выключен; не включаем его автоматически','shield',chip('Недоступно','yellow'))}${row('Внешний IP','Запрос ещё не выполнялся','globe',chip('Не запрашивался'))}${help('Нет данных не означает отсутствие проблемы','Отчёт сохраняет ошибку источника, время, ограничение и полноту. Недоступные строки не превращаются в пустой успешный список.')}`)}`,
  report:()=>panel('Сохранить отчёт',`<p>Один локальный файл: текущий снимок, закреплённая база, изменения и очищенный журнал LerNET.</p><div class="checklist"><div>${icon('check')}Настройки адаптеров, маршрутов и доступные DNS / прокси</div><div>${icon('check')}Пояснения, причины выводов и источники</div><div>${icon('check')}Версия клиента и состояние активной схемы</div><div>${icon('check')}Последние 400 строк журнала без секретов подключения</div></div><div class="divider"></div><label class="check"><input type="checkbox" checked><span>Удалить идентификаторы пользователя и чувствительные значения перед экспортом</span></label>${notice('Отчёт может содержать локальные адреса и имена приложений','Файл сохраняется на устройстве. Перед отправкой другому человеку можно посмотреть состав.','','eye')}${actions(link('sources','Посмотреть состав')+btn('Сохранить JSON','download-report','primary','download'))}`),
  settings:()=>`<div class="two"><div class="stack">${panel('Запуск и удобство',`${select('default-mode','Запускать по умолчанию',['Полный VPN','Прокси'])}${toggle('start-app','Запускать при входе в систему','Экспертный TUN включается по отдельной сохранённой настройке.',false)}${toggle('reduce-motion','Меньше движения','Уменьшить анимации и перемещения интерфейса.',false)}${row('Защита при сбое','Правила для отказа выхода и TUN','shield',link('protection','Настроить','small'))}`)}${panel('Проверка активных выходов',`${field('health-min','Минимальный интервал, секунды','3','','number')}${field('health-max','Максимальный интервал, секунды','7','Случайный интервал в заданных пределах. Проверяем именно путь через активный выход.','number')}${select('health-errors','Неудачи до восстановления',['2 подряд','3 подряд'])}${help('Спящие выходы','Не проверяются постоянно. Таймаут активной проверки отделён от долгой ручной проверки профиля.')}`)}</div><div class="stack">${panel('Параметры сети',`${field('dns-default','DNS по умолчанию','1.1.1.1')}${field('mtu-default','MTU TUN','1500','Защищённые ветки имеют собственную политику DNS.','number')}${select('manual-timeout','Ручная проверка профиля',['30 секунд','45 секунд'])}`)}${panel('Данные и версия',`${select('history-time','Хранить историю',['1 день','7 дней','Не хранить'])}${row('Журнал','Этапы и причины без секретов','file',link('logs','Открыть','small'))}${row('LerNET v1.1.0','Версия ядра показана отдельно в технических сведениях','info',link('updates','Обновления','small'))}${actions(btn('Сохранить настройки','save-settings','primary','check'))}`)}</div></div>`,
  protection:()=>`<div class="two">${panel('Защита веток',`${toggle('protect-exit','При отказе выхода — запрет','Для веток без явно разрешённого прямого fallback.')}${toggle('protect-dns','DNS следует защите ветки','Имя не разрешается через запрещённый прямой путь.')}${toggle('protect-ipv6','Применять к IPv4 и IPv6','Правило не ограничивается одним семейством адресов.')}${help('Проверяемая гарантия','Отказ выбранного профиля не переводит защищённое соединение на обычный интернет.')}`)}${panel('Если исчез общий TUN',`${notice(mobile?'Системная блокировка требует настройки Android':'Нужна системная защита Windows',mobile?'Для блокировки при остановке VPN включите Always-on и «Блокировать без VPN» в системных настройках. Это системная защита всего профиля, а не выборочная блокировка веток.':'Уровень WFP и служба должны сохранять нужный запрет независимо от интерфейса приложения. Пока это не подтверждено, интерфейс явно показывает ограничение.','warning','shield')}${kv([['Отказ отдельного выхода',chip('Запрет действует','good')],['Падение обработчика',chip('Системная защита не настроена','yellow')],['Ручное выключение','Показать последствия до остановки']])}${actions(btn(mobile?'Открыть системные настройки':'Настроить системную защиту','system-protection','','shield'))}${help('Возврат обычной сети','Удаляются только собственные временные изменения LerNET. Чужие фильтры, DNS и маршруты не сбрасываются без отдельного разбора.')}`)}</div>`,
  updates:()=>panel('LerNET v1.1.0',`<div class="inline">${chip('Доступно обновление','accent','download')}<small>Источник: GitHub / LernardDranrel / LerNET</small></div><div class="divider"></div><h3>Что нового</h3><div class="checklist"><div>${icon('check')}Экспертная схема поверх общего TUN</div><div>${icon('check')}Выходы в профили и папки, холодный запуск</div><div>${icon('check')}Понятный путь каждого соединения и защита при отказе</div></div>${help(mobile?'Установка Android':'Обновление Windows',mobile?'Скачать APK и разрешить установку из выбранного источника. Подтверждение обновления выполняет Android.':'Проверить файл, сохранить данные, корректно остановить LerNET и открыть установщик. После обновления можно запустить приложение сразу.')}${actions(btn(mobile?'Скачать APK':'Скачать и обновить','start-update','primary','download')+btn('Проверить снова','refresh'))}<details class="accordion"><summary>Источник и проверка файла</summary><div>Показываем URL релиза, версию, имя файла и результат проверки доступного SHA-256. Проверка хеша без доверенной подписи подтверждает целостность, но не независимую подлинность издателя.</div></details>`),
  'update-progress':()=>panel(mobile?'Обновление Android':'Обновление LerNET',`<div class="flow-steps">${step(1,'Файл получен','LerNET-1.1.0'+(mobile?'.apk':'-install.exe'))}${step(2,'Проверка завершена','Имя, версия и контрольная сумма совпали с опубликованными данными.')}${step(3,mobile?'Ожидается системное подтверждение':'Приложение готовится к остановке',mobile?'Android подтвердит установку поверх текущей версии.':'Профили и схема сохранены. Установщик покажет «Обновление», закроет приложение и заменит файлы.')}</div><div class="progress"><span style="width:72%"></span></div><small>Состояние процесса обновления · пример</small>${mobile?'':'<label class="check"><input type="checkbox" checked>Запустить LerNET после обновления</label>'}${state==='error'?notice('Обновление не завершено','Предыдущая версия и данные сохранены. Можно повторить загрузку.','error'):''}${actions(btn('Повторить','start-update','primary')+link('updates','Вернуться'))}`)
 };
 function step(n,title,body){return `<div class="flow-step"><span class="step-number">${n}</span><div><h3>${title}</h3><p>${body}</p></div></div>`;}
 function chooser(title,body,ico,target){return `<a href="#${target}" class="chooser">${appIcon(ico)}<span class="grow"><strong>${title}</strong><small>${body}</small></span>${icon('chevron')}</a>`;}
 function radio(name,value,title,body,on=false){return `<label class="policy-option"><input type="radio" name="${name}" value="${value}" ${on?'checked':''}><span><strong>${title}</strong><p>${body}</p></span></label>`;}
 function timeline(items){return `<div class="timeline">${items.map(([time,title,body])=>`<article class="timeline-item"><time>${time}</time><span class="marker"></span><div><strong>${title}</strong><p>${body}</p></div></article>`).join('')}</div>`;}
 function exitRows(){return row('Германия',state==='blocked'?'Все кандидаты недоступны':'Германия-2 · мессенджеры · 6 соединений','folder',link('exit-detail',state==='blocked'?'Недоступен':'Работает','small '+(state==='blocked'?'danger':'good')))+row('Нидерланды','До первого подходящего запроса','moon',btn('Спит · пробудить','wake','small'))+row('Корпоративный выход','Требуется настройка провайдера и интерфейса','laptop',link('target-picker','Настроить','small'));}
 function trafficRows(){return [['Telegram','telegram','example.org','Германия-2','82,3 КБ','vpn'],['Firefox','firefox','docs.example.org','Напрямую','142 КБ','direct'],['Служба приложения','laptop','telemetry.example','Запрет','0 Б','blocked'],['Неизвестный владелец','info','203.0.113.44:443','Напрямую · правило иначе','2,1 КБ','unknown']].map(([name,ico,host,path,bytes,type])=>`<tr data-search="${(name+' '+host+' '+path).toLowerCase()}" data-traffic="${type}"><td><div class="inline">${appIcon(ico,ico==='telegram'?'T':'') }<span>${name}<small>${mobile?'Пакет / UID':'Процесс / PID'}</small></span></div></td><td><strong>${host}</strong><small class="${type==='blocked'?'red':''}">${path}</small></td><td>${bytes}</td><td><a class="icon-btn" href="#connection${type==='blocked'?'?state=blocked':''}" aria-label="Путь соединения ${name}">${icon('chevron')}</a></td></tr>`).join('');}
 function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
 function navigate(id,s=''){location.hash=url(id,s);}
 function transition(s){location.hash=url(screen,s);}
 function confirm(title,body,label,action){opener=document.activeElement;dialog.innerHTML=`<h2>${title}</h2><p>${body}</p><div class="actions">${btn('Отмена','close-dialog')}${btn(label,action,'primary')}</div>`;dialog.showModal();dialog.querySelector('button').focus();}
 function showMenu(folder){opener=document.activeElement;dialog.innerHTML=`<h2>${folder?'Настройки папки':'Действия с профилем'}</h2><div class="chooser-list">${chooser('Маршрут','Открыть дерево правил','route','schema')}${chooser(folder?'Автоматическая смена':'Запуск и сон',folder?'Выбор кандидата и действия при отказе':'Режим активности выхода',folder?'swap':'moon',folder?'folder-policy':'lifecycle')}${chooser('Редактировать','Название и параметры','edit',folder?'folder':'profile-edit')}</div><div class="actions">${btn('Удалить','delete-item','danger','trash')}${btn('Закрыть','close-dialog')}</div>`;dialog.showModal();}
 function download(name,data){const href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),1500);toast('Сохранён демонстрационный файл. Данные устройства не считывались.');}
 function runAction(action,el){
  const go={settings:'settings','select-apps':'rule','import-confirm':'folder','system-protection':'permission','start-update':'update-progress'};
  if(go[action]){dialog.close();navigate(go[action]);if(action==='import-confirm')toast('Пример: профиль добавлен без остановки общего TUN.');return;}
  if(action==='close-dialog'){dialog.close();return;}
  if(action==='connect'||action==='expert-toggle'){if(state==='permission'){navigate('permission');return;}if(state==='off'){transition('ready');}else confirm('Выключить '+(action==='connect'?'VPN':'экспертный режим')+'?','При остановке обработки поведение защищённых веток зависит от системной защиты. Обычный прямой доступ восстановится для разрешённого трафика.','Выключить','confirm-stop');return;}
  if(action==='confirm-stop'){dialog.close();transition('off');return;}
  if(action==='grant'){confirm('Системное разрешение','В приложении здесь появится системный запрос '+(mobile?'Android на VPN':'Windows на права администратора')+'. Макет разрешения не запрашивает.','Продолжить пример','grant-confirm');return;}
  if(action==='grant-confirm'){dialog.close();navigate('expert');toast('Пример: разрешение получено, предпочитаемый режим сохранён.');return;}
  if(action==='probe'||action==='refresh'||action==='wake'){const id=screen;transition(action==='wake'?'waking':'loading');setTimeout(()=>{if(screen===id){transition('ready');toast(action==='wake'?'Пример: выход проснулся. Общий TUN продолжил работу.':'Демонстрационные данные обновлены.');}},1000);return;}
  if(action==='cancel-loading'){transition('ready');return;}
  if(action==='folder-menu'||action==='profile-menu'){showMenu(action==='folder-menu');return;}
  if(action==='delete-item'){confirm('Удалить элемент?','Связанные правила сохранят черновик с недоступной целью. Действующая схема не меняется до применения.','Удалить','confirm-delete');return;}
  if(action==='confirm-delete'){dialog.close();dirty=true;toast('Элемент удалён из черновика. Можно отменить.');return;}
  if(action==='discard'){confirm('Отменить черновик?','Вернуться к действующей схеме №'+revision+'. Работающие соединения останутся как есть.','Отменить изменения','confirm-discard');return;}
  if(action==='confirm-discard'){dirty=false;dialog.close();transition('ready');render();return;}
  if(action==='apply'){confirm('Применить схему?','Новые соединения используют новую версию. Добавленные запреты прекращают совпадающие соединения. Общий TUN продолжает работу.','Применить','confirm-apply');return;}
  if(action==='confirm-apply'){dialog.close();if(state==='error'){toast('Пример отказа: работает схема №'+revision+', черновик сохранён.');return;}dirty=false;revision++;transition('ready');render();toast('Пример: применена схема №'+revision+'.');return;}
  if(action==='commit-pattern'){const input=document.getElementById('rule-domain');if(!input.value.trim()){input.focus();toast('Введите домен или шаблон.');return;}document.getElementById('patterns').insertAdjacentHTML('beforeend',`<span class="pill">${esc(input.value.trim())}</span>`);input.value='';input.focus();dirty=true;return;}
  if(action==='remove-pill'){el.closest('.pill').remove();dirty=true;return;}
  if(action==='sample-import'){document.getElementById('import-text').value=JSON.stringify({format:'lernet-demo',version:2,profiles:[{name:'Германия-3',protocol:'vless',host:'vpn.example.net'}]},null,2);return;}
  if(action==='import-link'){el.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===el));document.getElementById('import-text').focus();return;}if(action==='choose-file'){document.getElementById('import-file').click();return;}
  if(action==='choose-exe'){document.getElementById('exe-file').click();return;}
  if(action==='qr'){confirm('Сканирование QR','В Android здесь откроется камера после разрешения. Для макета доступен локальный пример.','Открыть пример','qr-example');return;}
  if(action==='qr-example'){dialog.close();runAction('sample-import');return;}
  if(action==='select-proxy'||action==='select-vpn'){confirm('Изменить режим подключения?','Переход выполняется с явным состоянием переподключения. Схема и профили сохраняются.','Переключить','confirm-mode');return;}
  if(action==='confirm-mode'){dialog.close();transition('waking');toast('Пример переключения режима.');return;}
  if(action==='traffic-all'||action==='traffic-blocked'||action==='traffic-unknown'){document.querySelectorAll('[data-traffic]').forEach(r=>r.hidden=action!=='traffic-all'&&r.dataset.traffic!==action.slice(8));el.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===el));return;}
  if(action==='apps-running'||action==='apps-all'){document.querySelectorAll('#app-list .row').forEach((r,i)=>r.hidden=action==='apps-running'&&i!==0);el.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===el));return;}
  if(action==='external-ip'){confirm('Запросить внешний IP?','В настоящем приложении выбранный внешний сервис увидит исходящий IP и время запроса. Сейчас будет показан только пример.','Показать пример','external-example');return;}
  if(action==='external-example'){dialog.close();toast('Пример: 203.0.113.24 · страна / оператор по ответу внешнего сервиса.');return;}
  if(action==='download-report'||action==='download-log'){download('LerNET-v1.1.0-demo-'+(action==='download-log'?'log':'report')+'.json',{demo:true,platform,clientVersion:'1.1.0',note:'Демонстрационный отчёт. Не содержит данных устройства.',snapshot:{route:'LerNET TUN',dns:'127.0.0.1'},baseline:{},changes:[],sourceCompleteness:'example'});return;}
  if(action==='zoom-in'||action==='zoom-out'||action==='zoom-reset'){zoom=action==='zoom-reset'?1:Math.max(.65,Math.min(1.6,zoom+(action==='zoom-in'?.15:-.15)));document.getElementById('graph').style.transform=`scale(${zoom})`;toast('Масштаб '+Math.round(zoom*100)+'%');return;}
  if(action==='navigation'){opener=document.activeElement;dialog.innerHTML=`<h2>Разделы LerNET</h2><div class="chooser-list">${[['vpn','Подключение'],['profiles','Профили'],['expert','Экспертный режим'],['network','Сеть устройства'],['settings','Настройки'],['logs','Журнал']].map(([id,name])=>chooser(name,'','route',id)).join('')}</div><div class="actions">${btn('Закрыть','close-dialog')}</div>`;dialog.showModal();return;}
  if(action==='pause'){el.innerHTML=icon('play')+' Продолжить';el.dataset.action='resume';toast('Пример: список остановлен для изучения.');return;}
  if(action==='resume'){el.innerHTML=icon('pause')+' Пауза';el.dataset.action='pause';return;}
  if(action==='save-settings'){toast('Настройки макета сохранены на текущем экране.');return;}
  if(action==='pin-baseline'){toast('Пример: текущий снимок закреплён для сравнения.');return;}
 }
 document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action&&action.tagName!=='SELECT'){runAction(action.dataset.action,action);return;}const a=e.target.closest('a[href^="#"]');if(a&&dialog.open)dialog.close();});
 document.addEventListener('input',e=>{if(e.target.matches('[data-search-input]')){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(q));}if(e.target.id==='reduce-motion')document.body.classList.toggle('reduced',e.target.checked);});
 document.addEventListener('change',async e=>{if(e.target.matches('[data-action="network-select"]'))navigate(e.target.value);if(e.target.matches('.scope-select')){scopeOwner=['device','folder','profile'][e.target.selectedIndex];if(screen==='schema')installGraph();toast('Редактируется: '+e.target.options[e.target.selectedIndex].text);}if(e.target.id==='graph-branch')installGraph(e.target.selectedIndex);if(e.target.id==='exe-file'&&e.target.files[0]){const name=e.target.files[0].name;document.getElementById('app-list').insertAdjacentHTML('beforeend',`<label class="row"><input type="checkbox" checked>${appIcon('laptop')}<span>${esc(name)}<small style="display:block">Выбран вручную · файл не запускается</small></span></label>`);}if(e.target.id==='import-file'&&e.target.files[0]){const file=e.target.files[0];if(file.size>2*1024*1024){toast('Для примера выберите файл до 2 МБ.');return;}document.getElementById('import-text').value=await file.text();toast('Файл прочитан локально. Проверьте содержимое перед добавлением.');}});
 document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const kind=form.dataset.form;if(kind==='import'){const input=document.getElementById('import-text');if(!input.value.trim()){input.setAttribute('aria-invalid','true');toast('Добавьте ссылку или содержимое файла.');input.focus();return;}if(!input.value.trim().startsWith('vless://')){try{JSON.parse(input.value);}catch{input.setAttribute('aria-invalid','true');toast('JSON повреждён. Исправьте его или выберите другой файл.');input.focus();return;}}navigate('import-review');return;}if(kind==='test-route'){document.getElementById('route-test-result').innerHTML=`<div class="flow-steps">${step(1,esc(document.getElementById('test-app').value),'Назначение: '+esc(document.getElementById('test-host').value))}${step(2,'Пример решения','Папка «Германия» · запрет при отказе.')}</div>${chip('Без сетевого запроса','good')}`;return;}if(kind==='system-route'){toast('Пример: показан выбранный маршрут; настоящий запрос к ОС не выполнялся.');return;}if(kind==='profile'){const port=Number(document.getElementById('profile-port').value);if(port<1||port>65535){toast('Порт должен быть от 1 до 65535.');document.getElementById('profile-port').focus();return;}navigate('profile');toast('Пример: профиль сохранён.');return;}dirty=true;navigate(kind==='rule'||kind==='redirect'?'schema':'exit-detail','draft');toast('Изменения сохранены в черновик.');});
 dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus();});
 document.addEventListener('keydown',e=>{if(dialog.open&&e.key==='Enter'&&!e.target.matches('input,textarea,select')){e.preventDefault();dialog.querySelector('.primary')?.click();return;}if((e.key==='Delete'||e.key==='Backspace')&&selectedNode&&!e.target.matches('input,textarea,select')){e.preventDefault();runAction('delete-item');}if(e.key==='Escape'&&selectedNode){selectedNode.classList.remove('selected');selectedNode=null;}if(e.ctrlKey&&e.key==='s'){e.preventDefault();runAction('apply');}});
 window.addEventListener('hashchange',()=>{render();document.getElementById('page-title').focus({preventScroll:true});window.scrollTo(0,0);});
 function installGraph(branch=0){
  const graph=document.getElementById('graph');if(!graph)return;selectedNode=null;
  const nodes=mobile?[
   ['root','Устройство','Все приложения','По умолчанию: напрямую',36,22,'root'],
   ['condition',branch===2?'Фоновая телеметрия':branch===1?'Нужные сайты':'Мессенджеры',branch===2?'telemetry.example':branch===1?'example.org':'Telegram или Signal','Условие · нажмите для свойств',36,156,''],
   ['channel',branch===2?'Запрет':'Общий канал',branch===2?'Доступ остановлен':'Мессенджеры','Связан с 2 ветками',36,286,branch===2?'deny':'shared'],
   ['exit',branch===2?'Результат':'Папка · Германия',branch===2?'Не покидает устройство':'Германия-2 · по запросу',branch===2?'Правило №4':'При отказе: запрет',36,416,branch===2?'deny':'shared']
  ]:[
   ['root','Устройство','Все приложения','По умолчанию: напрямую',358,30,'root'],
   ['condition','Условие','Мессенджеры','Telegram или Signal',30,190,''],
   ['sites','Условие','Нужные сайты','example.org',358,190,''],
   ['telemetry','Условие','Фоновая телеметрия','telemetry.example',686,190,''],
   ['channel','Общий канал','Мессенджеры','Портал · 2 входящие ветки',194,352,'shared'],
   ['deny','Результат','Запрет','Трафик не покидает устройство',686,352,'deny'],
   ['exit','Выход','Папка · Германия','Германия-2 · при отказе запрет',194,497,'shared']
  ];
  if(scopeOwner!=='device'){const first=nodes[0];first[1]=scopeOwner==='folder'?'Папка · Германия':'Профиль · Германия-2';first[2]='Дочерняя схема';first[3]='Явная область маршрута';}
  graph.innerHTML='<svg class="edges" aria-hidden="true"></svg>'+nodes.map(([id,kind,title,sub,x,y,tone])=>`<button class="graph-node ${tone}" data-node="${id}" style="left:${x}px;top:${y}px" aria-label="${title}: ${sub}"><div class="node-kind">${kind}</div><strong>${id==='channel'?icon('portal'):''} ${title}</strong><small>${sub}</small></button>`).join('');
  graph.style.height=mobile?'555px':'645px';graph.style.transform=`scale(${zoom})`;
  const pairs=mobile?[['root','condition'],['condition','channel'],['channel','exit']]:[['root','condition'],['root','sites'],['root','telemetry'],['condition','channel'],['sites','channel'],['telemetry','deny'],['channel','exit']];
  function edges(){graph.querySelector('.edges').innerHTML=pairs.map(([a,b])=>{const from=graph.querySelector(`[data-node="${a}"]`),to=graph.querySelector(`[data-node="${b}"]`);const x1=from.offsetLeft+from.offsetWidth/2,y1=from.offsetTop+from.offsetHeight,x2=to.offsetLeft+to.offsetWidth/2,y2=to.offsetTop,mid=y1+(y2-y1)/2;return `<path d="M${x1},${y1} V${mid} H${x2} V${y2}"/>`;}).join('');}
  edges();
  graph.querySelectorAll('[data-node]').forEach(node=>{
   let timer,ghost,down,dragged=false;
   node.addEventListener('click',()=>{if(dragged){dragged=false;return;}selectedNode?.classList.remove('selected');selectedNode=node;node.classList.add('selected');toast('Выбрано: '+node.querySelector('strong').textContent.trim()+'. Двойное нажатие открывает свойства.');});
   node.addEventListener('dblclick',()=>navigate(node.dataset.node==='channel'||node.dataset.node==='exit'?'exit-detail':'rule'));
   node.addEventListener('keydown',e=>{if(e.key==='Enter')navigate(node.dataset.node==='channel'||node.dataset.node==='exit'?'exit-detail':'rule');});
   node.addEventListener('pointerdown',e=>{if(e.button!==0)return;down={x:e.clientX,y:e.clientY,left:node.offsetLeft,top:node.offsetTop,pointer:e.pointerId};timer=setTimeout(()=>{ghost=node.cloneNode(true);ghost.classList.add('drag-ghost');ghost.style.left=down.x+'px';ghost.style.top=down.y+'px';ghost.style.width=node.offsetWidth+'px';ghost.removeAttribute('data-node');ghost.removeAttribute('aria-label');ghost.setAttribute('aria-hidden','true');ghost.removeAttribute('tabindex');document.body.appendChild(ghost);node.style.opacity='.35';node.setPointerCapture(e.pointerId);dragged=true;},340);});
   node.addEventListener('pointermove',e=>{if(!down)return;if(ghost){ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}else if(Math.hypot(e.clientX-down.x,e.clientY-down.y)>12)clearTimeout(timer);});
   function end(e){clearTimeout(timer);if(ghost&&down){node.style.left=Math.max(0,Math.min(graph.offsetWidth-node.offsetWidth,down.left+(e.clientX-down.x)/zoom))+'px';node.style.top=Math.max(0,Math.min(graph.offsetHeight-node.offsetHeight,down.top+(e.clientY-down.y)/zoom))+'px';ghost.remove();ghost=null;node.style.opacity='';dirty=true;edges();toast('Положение изменено в черновике.');}down=null;}
   node.addEventListener('pointerup',end);node.addEventListener('pointercancel',e=>{clearTimeout(timer);ghost?.remove();ghost=null;node.style.opacity='';down=null;});
  });
 }
 render();
})();
